import { Component, EventEmitter, Output } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { I18nService, Lang } from './i18n.service';

@Component({
  selector: 'app-lang-switch',
  standalone: true,
  imports: [CommonModule, FormsModule],
  template: `
    <label class="lang-switch">
      <span class="lang-label">Language</span>
      <select [(ngModel)]="lang" (ngModelChange)="onChange($event)">
        <option value="pt">Português</option>
        <option value="en">English</option>
      </select>
    </label>
  `,
  styles: [`
    .lang-switch { display:flex; align-items:center; gap:8px; }
    .lang-label { font-size: 12px; opacity: .8; }
    select { padding: 6px 8px; border-radius: 8px; border: 1px solid rgba(0,0,0,.15); }
  `]
})
export class LangSwitchComponent {
  @Output() langChanged = new EventEmitter<Lang>();

  lang: Lang;

  constructor(private i18n: I18nService) {
    this.lang = this.i18n.getLang();
  }

  onChange(next: Lang): void {
    this.i18n.setLang(next);
    this.langChanged.emit(next);
  }
}
